def solve(a, b):
    """Return Levenshtein edit distance between strings a and b.
    Operations: insertion, deletion, substitution, each cost 1.
    """
    n, m = len(a), len(b)
    # Ensure the shorter string is b to use O(min(n,m)) space if desired, but simple 2D is fine.
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j
    for i in range(1, n + 1):
        ai = a[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                cost = 0
            else:
                cost = 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,      # deletion
                dp[i][j - 1] + 1,      # insertion
                dp[i - 1][j - 1] + cost  # substitution
            )
    return dp[n][m]

